thread_local! {
    static CURRENT_TRANSACTION: RefCell<Option<Transaction>> = RefCell::new(None);
}

fn execute_transaction(tx: Transaction) {
    CURRENT_TRANSACTION.with(|current| {
        *current.borrow_mut() = Some(tx); // Sets thread-local context
    });
    perform_operations();
    // CRITICAL BUG: Forgot to clean up CURRENT_TRANSACTION upon completion!
}
